                        theme: {
                            ink: "#120a0e",
                            paper: "#ece7e4",
                            sand: "#e0d8cb",
                            card: "#0d070a",
                            thumb: "#f4f1ec",
                            accent: "#7ec9a2",
                            fontHeading: "'Bdogrotesk Bf 648 A 656 Fc 86 B 8',Arial,sans-serif",
                            fontBody: "'Inter', system-ui, -apple-system, sans-serif",
                            googleFonts: ["Inter:wght@400;500;600"],
                        },
                        links: {
                            yearly: "https://www.radianttemplates.com/template-vault",
                            lifetime: "https://www.radianttemplates.com/template-vault",
                        },
                        trigger: {
