                        heading: "Stop buying templates\none at a time.",
                        lead: "**$18,000+** of premium templates. Own the whole vault for the price of one — or let two land in your account every month.",
                        anchor: "Buy them one by one: ~~$18,000+~~ · own all 190 for **$499**.",
                        tiers: {
                            yearly: {
                                name: "Yearly",
                                price: "$499",
                                per: "/yr · $41.58 mo billed yearly",
                                desc: "**3 templates every month** — 36 a year. Yours to keep, forever.",
                                cta: "Start yearly",
                            },
                            lifetime: {
                                name: "Lifetime",
                                price: "$599",
                                per: "~~$2399~~ founding · all 190",
                                badge: "Most popular",
                                once: "∞ Pay once. Yours forever.",
                                desc: "All 190 today + every future template. Source files, sections library, priority. No renewals.",
                                cta: "Own the vault →",
                            },
                        },
                        note: "First **500** members only — then lifetime returns to its regular $2399.",
                        reassure:
                            "**Already a customer?** The $179 you paid credits toward any plan — go yearly for $120 more, or own it for life for $320.",
                        templates: [
                            {
                                n: "Constrax",
                                cat: "Construction",
                                c: "#8a8256",
                                img: "https://cdn.prod.website-files.com/65bc778da6983c7153fa5178/6a54d0841f8ec52f938b943d_Constrax-main-thumbnail.avif",
                            },
                            {
                                n: "Konstruk",
                                cat: "Construction",
                                c: "#8a8256",
                                img: "https://cdn.prod.website-files.com/65bc778da6983c7153fa5178/6a54d09fb662e7aa383fc281_Konstruk-main-thumbnail.avif",
                            },
                            {
                                n: "Buildex",
                                cat: "Construction",
                                c: "#8a8256",
                                img: "https://cdn.prod.website-files.com/65bc778da6983c7153fa5178/6a54d0b7a82704928631b74c_Buildex_Buildex-main-thumbnail.avif",
                            },
                            {
                                n: "Konstructor",
                                cat: "Construction",
                                c: "#8a8256",
                                img: "https://cdn.prod.website-files.com/65bc778da6983c7153fa5178/6a54d0dd36e990a2e22e70ac_Konstructor-main-thumbnail.webp",
                            },
                            {
