                                c: "#8a8256",
                                img: "https://cdn.prod.website-files.com/65bc778da6983c7153fa5178/6a54d13cf590e02a7d08d733_Kontix-Main-Thumbnail.webp",
                            },
                        ],
                    };
                /* CONFIG_END */
                // ---------- helpers ----------
                function md(s) {
                    return String(s == null ? "" : s)
                        .replace(/~~([^~]+)~~/g, "<s>$1</s>")
                        .replace(/\*\*([^*]+)\*\*/g, "<b>$1</b>")
                        .replace(/\n/g, "<br>");
                }
                function hexToRgba(h, a) {
                    h = String(h || "#000").replace("#", "");
                    if (h.length === 3) h = h.replace(/./g, "$&$&");
                    var n = parseInt(h, 16);
                    return "rgba(" + ((n >> 16) & 255) + "," + ((n >> 8) & 255) + "," + (n & 255) + "," + a + ")";
                }
                function merge(base, over) {
                    var out = {},
                        k;
                    for (k in base) out[k] = base[k];
                    if (over)
                        for (k in over) {
                            if (
                                over[k] &&
                                typeof over[k] === "object" &&
                                !Array.isArray(over[k]) &&
                                typeof out[k] === "object"
                            ) {
                                out[k] = merge(out[k], over[k]);
                            } else out[k] = over[k];
                        }
                    return out;
                }
                function ready(fn) {
                    if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", fn);
                    else fn();
                }

                // ---------- theme ----------
                function applyTheme(el, t) {
                    t = t || {};
                    el.style.setProperty("--ink", t.ink || "#120a0e");
                    el.style.setProperty("--paper", t.paper || "#ece7e4");
                    el.style.setProperty("--sand", t.sand || "#e0d8cb");
                    el.style.setProperty("--card", t.card || "#0d070a");
                    el.style.setProperty("--thumb", t.thumb || "#f4f1ec");
                    el.style.setProperty("--accent", t.accent || "#7ec9a2");
                    el.style.setProperty("--rvf-h", t.fontHeading || "'Fraunces', Georgia, serif");
                    el.style.setProperty("--rvf-b", t.fontBody || "'Inter', system-ui, sans-serif");
                    el.style.setProperty("--line", hexToRgba(t.paper || "#ece7e4", 0.14));
                    el.style.setProperty("--mut", hexToRgba(t.paper || "#ece7e4", 0.55));
                }

                // ---------- markup ----------
                function imgURL(cdn, t) {
                    if (!t.img) return "";
                    if (/^https?:\/\//.test(t.img) || /^data:/.test(t.img)) return t.img;
                    return cdn ? cdn + t.img : "";
                }
                function fauxShot(c) {
                    return (
                        '<div class="rt-vlt-shot" style="--c:' +
                        c +
                        '">' +
                        '<div class="rt-vlt-topbar"><i></i><i></i><i></i><b></b></div>' +
                        '<span class="rt-vlt-h1"></span><span class="rt-vlt-h2"></span><span class="rt-vlt-btn"></span>' +
                        '<div class="rt-vlt-imgs"><span></span><span></span></div></div>'
                    );
                }
                function card(cdn, t) {
                    var u = imgURL(cdn, t);
                    var shot = u
                        ? '<div class="rt-vlt-shot rt-vlt-shot--img"><img src="' +
                          u +
                          '" alt="' +
                          t.n +
                          ' template" loading="lazy" data-c="' +
                          t.c +
                          '"></div>'
                        : fauxShot(t.c);
                    return (
                        '<div class="rt-vlt-card">' +
                        shot +
                        '<div class="rt-vlt-cap"><strong>' +
                        t.n +
                        "</strong><em>" +
                        (t.cat || "") +
                        "</em></div></div>"
                    );
                }
                function buildHTML(cfg) {
                    var reel = cfg.templates
                        .concat(cfg.templates)
                        .map(function (t) {
                            return card(cfg.cdn, t);
                        })
                        .join("");
                    var y = cfg.tiers.yearly,
                        l = cfg.tiers.lifetime;
                    return (
                        "" +
                        '<button class="rt-vlt-trigger" id="rtVltOpen" aria-label="Open the vault">' +
                        '<span class="rt-vlt-mark">' +
                        cfg.trigger.mark +
                        "</span>" +
                        "<span><b>" +
                        cfg.trigger.title +
                        '</b><br><span class="rt-vlt-sub">' +
                        cfg.trigger.sub +
                        "</span></span>" +
                        '<span class="rt-vlt-pulse"></span>' +
                        "</button>" +
                        '<div class="rt-vlt-overlay" id="rtVltOverlay" role="dialog" aria-modal="true" aria-label="Radiant vault">' +
                        '<div class="rt-vlt-modal">' +
                        '<div class="rt-vlt-promo">' +
                        cfg.banner +
                        "</div>" +
                        '<button class="rt-vlt-x" id="rtVltClose" aria-label="Close"><svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M4 4l8 8M12 4l-8 8" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg></button>' +
                        '<div class="rt-vlt-wall"><div class="rt-vlt-row rt-vlt-r1">' +
                        reel +
                        "</div></div>" +
                        '<div class="rt-vlt-body">' +
                        '<span class="rt-vlt-ey"><span class="rt-vlt-dot"></span>' +
                        cfg.eyebrow +
                        "</span>" +
                        "<h3>" +
                        md(cfg.heading) +
                        "</h3>" +
                        '<p class="rt-vlt-lead">' +
                        md(cfg.lead) +
                        "</p>" +
                        '<div class="rt-vlt-anchor">' +
                        md(cfg.anchor) +
                        "</div>" +
                        '<div class="rt-vlt-tiers">' +
                        '<div class="rt-vlt-tier">' +
                        '<div class="rt-vlt-nm">' +
                        y.name +
                        "</div>" +
                        '<span class="rt-vlt-price">' +
                        y.price +
                        '</span> <span class="rt-vlt-per">' +
                        md(y.per) +
                        "</span>" +
                        '<p class="rt-vlt-td">' +
                        md(y.desc) +
                        "</p>" +
                        '<a class="rt-vlt-cta g" href="' +
                        cfg.links.yearly +
                        '" target="_blank" rel="noopener">' +
                        y.cta +
                        "</a>" +
                        "</div>" +
                        '<div class="rt-vlt-tier feat">' +
                        (l.badge ? '<span class="rt-vlt-badge">' + l.badge + "</span>" : "") +
                        '<div class="rt-vlt-nm">' +
                        l.name +
                        "</div>" +
                        '<span class="rt-vlt-price">' +
                        l.price +
                        '</span> <span class="rt-vlt-per">' +
                        md(l.per) +
                        "</span>" +
                        (l.once ? '<div><span class="rt-vlt-once">' + l.once + "</span></div>" : "") +
                        '<p class="rt-vlt-td2">' +
                        md(l.desc) +
                        "</p>" +
                        '<a class="rt-vlt-cta p" href="' +
                        cfg.links.lifetime +
                        '" target="_blank" rel="noopener">' +
                        l.cta +
                        "</a>" +
                        "</div>" +
                        "</div>" +
                        '<div class="rt-vlt-note"><svg width="14" height="14" viewBox="0 0 16 16" fill="none"><path d="M8 1.5c1 2.5 3 3.5 3 6a3 3 0 11-6 0c0-2.5 2-3.5 3-6z" stroke="currentColor" stroke-width="1.2" stroke-linejoin="round"/></svg><span>' +
                        md(cfg.note) +
                        "</span></div>" +
                        '<div class="rt-vlt-reassure"><svg width="15" height="15" viewBox="0 0 16 16" fill="none"><path d="M8 13.5S2.5 10 2.5 6.2A2.7 2.7 0 018 4.3a2.7 2.7 0 015.5 1.9C13.5 10 8 13.5 8 13.5z" stroke="currentColor" stroke-width="1.1" stroke-linejoin="round"/></svg><span>' +
                        md(cfg.reassure) +
                        "</span></div>" +
                        "</div>" +
                        "</div>" +
                        "</div>"
                    );
                }

                // ---------- render ----------
                function ensureFonts(theme) {
                    var fams = (theme && theme.googleFonts) || [];
                    // backward-compat: old configs with no googleFonts list but still using Fraunces
                    if (!fams.length && theme && /Fraunces/i.test((theme.fontHeading || "") + (theme.fontBody || "")))
                        fams = ["Fraunces:opsz,wght@9..144,300;9..144,400"];
                    if (!fams.length) return; // template's own font in use — nothing to load
                    var href =
                        "https://fonts.googleapis.com/css2?family=" +
                        fams
                            .map(function (f) {
                                return String(f).replace(/ /g, "+");
                            })
                            .join("&family=") +
                        "&display=swap";
                    var link = document.getElementById("rtVaultFonts");
                    if (link) {
                        if (link.getAttribute("href") !== href) link.setAttribute("href", href);
                        return;
                    }
                    link = document.createElement("link");
                    link.id = "rtVaultFonts";
                    link.rel = "stylesheet";
                    link.href = href;
                    document.head.appendChild(link);
                }
                function ensureCss() {
                    if (document.getElementById("rtVaultCss")) return;
                    var s = document.createElement("style");
                    s.id = "rtVaultCss";
                    s.textContent = CSS;
                    document.head.appendChild(s);
                }

                // container is optional (defaults to body). opts.preview => inline, always-open, unwired.
                function render(cfg, container, opts) {
                    opts = opts || {};
                    cfg = merge(DEFAULTS, cfg || {});
                    ensureFonts(cfg.theme);
                    ensureCss();
                    var host = container || document.body;
                    if (opts.preview) host.innerHTML = "";
                    else if (document.querySelector(".rt-vlt-root")) return null; // mount once

                    var root = document.createElement("div");
                    root.className = "rt-vlt-root" + (opts.preview ? " rt-vlt-preview" : "");
                    applyTheme(root, cfg.theme);
                    root.innerHTML = buildHTML(cfg);
                    host.appendChild(root);

                    // broken thumbnails fall back to the faux card (no broken-image icons)
                    Array.prototype.forEach.call(root.querySelectorAll(".rt-vlt-shot--img img"), function (im) {
                        im.addEventListener("error", function () {
                            var shot = im.parentNode;
                            if (shot) shot.outerHTML = fauxShot(im.getAttribute("data-c") || "#8a8256");
                        });
                    });

                    var ov = root.querySelector("#rtVltOverlay");
                    if (opts.preview) {
                        ov.classList.add("open");
                        return root;
                    }

                    function show() {
                        ov.classList.add("open");
                        document.body.style.overflow = "hidden";
                    }
                    function hide() {
                        ov.classList.remove("open");
                        document.body.style.overflow = "";
                    }
                    root.querySelector("#rtVltOpen").addEventListener("click", show);
                    root.querySelector("#rtVltClose").addEventListener("click", hide);
                    ov.addEventListener("click", function (e) {
                        if (e.target === ov) hide();
                    });
                    document.addEventListener("keydown", function (e) {
                        if (e.key === "Escape") hide();
                    });
                    return root;
                }

