                    render(window.RADIANT_VAULT_CONFIG || {}, document.body, {});
                }

                var CSS = [
                    ".rt-vlt-root{--ink:#120a0e;--paper:#ece7e4;--sand:#e0d8cb;--card:#0d070a;--thumb:#f4f1ec;--accent:#7ec9a2;--line:rgba(233,228,226,.14);--mut:rgba(236,231,228,.55);--rvf-h:'Fraunces',Georgia,serif;--rvf-b:'Inter',system-ui,-apple-system,sans-serif;font-family:var(--rvf-b)}",
                    ".rt-vlt-root *{box-sizing:border-box}",
                    ".rt-vlt-root h3{font-family:var(--rvf-h);font-weight:300;letter-spacing:-.015em;margin:11px 0 9px;color:var(--paper);font-size:29px;line-height:1.04}",
                    ".rt-vlt-trigger{position:fixed;left:22px;bottom:22px;z-index:99998;display:flex;align-items:center;gap:11px;background:var(--ink);color:var(--paper);border:1px solid rgba(224,216,203,.3);border-radius:999px;padding:11px 17px 11px 13px;cursor:pointer;box-shadow:0 18px 40px -18px rgba(0,0,0,.65);transition:transform .35s cubic-bezier(.22,1,.36,1),box-shadow .4s;font-size:13.5px;text-align:left;line-height:1.3}",
                    ".rt-vlt-trigger:hover{transform:translateY(-3px);box-shadow:0 26px 54px -20px rgba(0,0,0,.7)}",
                    ".rt-vlt-trigger .rt-vlt-mark{width:30px;height:30px;border-radius:50%;background:var(--sand);color:var(--ink);display:flex;align-items:center;justify-content:center;flex:none;font-family:var(--rvf-h);font-size:12px}",
                    ".rt-vlt-trigger b{font-weight:500}",
                    ".rt-vlt-trigger .rt-vlt-sub{color:var(--mut);font-size:11.5px}",
                    ".rt-vlt-pulse{position:absolute;top:-4px;right:-4px;width:11px;height:11px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 0 rgba(126,201,162,.6);animation:rtvpulse 2.4s infinite}",
                    "@keyframes rtvpulse{0%{box-shadow:0 0 0 0 rgba(126,201,162,.5)}70%{box-shadow:0 0 0 9px rgba(126,201,162,0)}100%{box-shadow:0 0 0 0 rgba(126,201,162,0)}}",
                    ".rt-vlt-overlay{position:fixed;inset:0;z-index:99999;background:rgba(9,5,7,.62);-webkit-backdrop-filter:blur(5px);backdrop-filter:blur(5px);display:flex;align-items:center;justify-content:center;padding:20px;opacity:0;visibility:hidden;transition:opacity .4s ease,visibility .4s}",
                    ".rt-vlt-overlay.open{opacity:1;visibility:visible}",
                    ".rt-vlt-modal{background:var(--ink);border:1px solid var(--line);border-radius:18px;overflow:hidden;position:relative;max-width:760px;width:100%;max-height:92vh;overflow-y:auto;color:var(--paper);transform:translateY(26px) scale(.985);transition:transform .5s cubic-bezier(.16,1,.3,1)}",
                    ".rt-vlt-overlay.open .rt-vlt-modal{transform:none}",
                    ".rt-vlt-x{position:absolute;top:12px;right:13px;width:36px;height:36px;border-radius:50%;background:var(--ink);border:1px solid rgba(224,216,203,.4);display:flex;align-items:center;justify-content:center;color:var(--paper);cursor:pointer;z-index:6;box-shadow:0 4px 14px rgba(0,0,0,.35);transition:background .3s,transform .35s}",
                    ".rt-vlt-x:hover{transform:rotate(90deg)}",
                    ".rt-vlt-promo{background:var(--sand);color:var(--ink);text-align:center;font-size:11.5px;letter-spacing:.05em;text-transform:uppercase;font-weight:600;padding:8px 52px 8px 12px}",
                    ".rt-vlt-wall{padding:14px 0 0;overflow:hidden;-webkit-mask-image:linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent);mask-image:linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent)}",
                    ".rt-vlt-row{display:flex;gap:14px;padding:5px 14px;width:max-content}",
                    ".rt-vlt-r1{animation:rtvL 46s linear infinite}",
                    ".rt-vlt-overlay:hover .rt-vlt-r1{animation-play-state:paused}",
                    "@keyframes rtvL{from{transform:translateX(0)}to{transform:translateX(-50%)}}",
                    ".rt-vlt-card{width:238px;flex:none}",
                    ".rt-vlt-shot{height:138px;border-radius:11px;background:var(--thumb);padding:12px;overflow:hidden;border:1px solid rgba(18,10,14,.06);box-shadow:0 12px 26px -18px rgba(0,0,0,.55)}",
                    ".rt-vlt-shot--img{padding:0;background:var(--card)}",
                    ".rt-vlt-shot--img img{width:100%;height:100%;object-fit:cover;object-position:top center;display:block}",
                    ".rt-vlt-topbar{display:flex;gap:5px;align-items:center;margin-bottom:12px}",
                    ".rt-vlt-topbar i{width:7px;height:7px;border-radius:50%;background:rgba(18,10,14,.14)}",
                    ".rt-vlt-topbar b{margin-left:auto;height:6px;width:44px;border-radius:3px;background:rgba(18,10,14,.1)}",
                    ".rt-vlt-h1{display:block;height:11px;width:78%;border-radius:3px;background:var(--c);margin-bottom:6px}",
                    ".rt-vlt-h2{display:block;height:8px;width:52%;border-radius:3px;background:var(--c);opacity:.45;margin-bottom:11px}",
                    ".rt-vlt-btn{display:inline-block;height:14px;width:52px;border-radius:7px;background:var(--c)}",
                    ".rt-vlt-imgs{display:flex;gap:7px;margin-top:12px}",
                    ".rt-vlt-imgs span{flex:1;height:28px;border-radius:6px;background:var(--c);opacity:.3}",
                    ".rt-vlt-cap{margin-top:9px;display:flex;justify-content:space-between;align-items:center}",
                    ".rt-vlt-cap strong{font-size:13.5px;font-weight:500;color:var(--paper)}",
                    ".rt-vlt-cap em{font-style:normal;font-size:10px;letter-spacing:.05em;text-transform:uppercase;color:var(--mut);border:1px solid var(--line);border-radius:999px;padding:2px 8px}",
                    ".rt-vlt-body{padding:20px 26px 26px}",
                    ".rt-vlt-ey{font-size:11.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--mut);display:flex;align-items:center;gap:8px}",
                    ".rt-vlt-dot{width:7px;height:7px;border-radius:50%;background:var(--accent);display:inline-block}",
                    ".rt-vlt-lead{font-size:13.5px;color:rgba(236,231,228,.7);line-height:1.5;margin:0;max-width:450px}",
                    ".rt-vlt-lead b{color:var(--paper)}",
                    ".rt-vlt-anchor{margin-top:14px;font-size:13px;color:var(--mut)}",
                    ".rt-vlt-anchor s{color:rgba(236,231,228,.4)}",
                    ".rt-vlt-anchor b{color:var(--paper)}",
                    ".rt-vlt-tiers{display:flex;gap:12px;margin-top:18px;flex-wrap:wrap}",
                    ".rt-vlt-tier{flex:1;min-width:220px;border:1px solid var(--line);border-radius:13px;padding:16px 18px;background:var(--card);position:relative}",
                    ".rt-vlt-tier.feat{border-color:var(--sand);background:rgba(224,216,203,.05)}",
                    ".rt-vlt-nm{font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--sand);margin-bottom:8px}",
                    ".rt-vlt-price{font-family:var(--rvf-h);font-size:31px;line-height:1}",
                    ".rt-vlt-per{font-size:12px;color:var(--mut)}",
                    ".rt-vlt-per s{opacity:.6}",
                    ".rt-vlt-once{display:inline-block;margin-top:6px;font-size:11px;letter-spacing:.05em;text-transform:uppercase;color:var(--accent);border:1px solid rgba(126,201,162,.3);border-radius:999px;padding:2px 9px}",
                    ".rt-vlt-td{font-size:12px;color:var(--mut);margin:8px 0 0;line-height:1.45}",
                    ".rt-vlt-td b{color:rgba(236,231,228,.85)}",
                    ".rt-vlt-td2{font-size:12px;color:rgba(236,231,228,.75);margin:9px 0 0;line-height:1.45}",
                    ".rt-vlt-badge{position:absolute;top:14px;right:14px;font-size:9.5px;letter-spacing:.07em;text-transform:uppercase;background:var(--sand);color:var(--ink);border-radius:999px;padding:3px 8px}",
                    ".rt-vlt-cta{display:block;text-align:center;margin-top:12px;border-radius:999px;padding:11px;font-size:13px;font-weight:500;cursor:pointer;transition:transform .3s;text-decoration:none}",
                    ".rt-vlt-cta:hover{transform:translateY(-1px)}",
                    ".rt-vlt-cta.p{background:var(--sand);color:var(--ink)}",
                    ".rt-vlt-cta.g{border:1px solid var(--line);color:var(--paper)}",
                    ".rt-vlt-note{margin-top:16px;font-size:12px;color:var(--mut);display:flex;align-items:center;gap:8px}",
                    ".rt-vlt-note svg{flex:none;color:var(--sand)}",
                    ".rt-vlt-note b{color:rgba(236,231,228,.85)}",
                    ".rt-vlt-reassure{margin-top:14px;font-size:12px;color:var(--mut);border-top:1px solid var(--line);padding-top:14px;display:flex;gap:8px;line-height:1.5}",
                    ".rt-vlt-reassure svg{flex:none;margin-top:2px;color:var(--sand)}",
                    ".rt-vlt-reassure b{color:rgba(236,231,228,.85)}",
                    ".rt-vlt-preview .rt-vlt-trigger{position:static;display:inline-flex;margin:0 0 16px}",
                    ".rt-vlt-preview .rt-vlt-overlay{position:relative;inset:auto;opacity:1;visibility:visible;background:transparent;-webkit-backdrop-filter:none;backdrop-filter:none;padding:0;display:block}",
                    ".rt-vlt-preview .rt-vlt-modal{transform:none;max-height:none}",
                    "@media(max-width:560px){.rt-vlt-trigger .rt-vlt-sub{display:none}.rt-vlt-body{padding:18px 18px 22px}}",
                    "@media(prefers-reduced-motion:reduce){.rt-vlt-r1{animation:none}.rt-vlt-pulse{animation:none}}",
                ].join("\n");

                // public API (used by the Studio GUI)
                window.RadiantVault = {
                    mount: mount,
                    render: render,
                    applyTheme: applyTheme,
                    md: md,
                    DEFAULTS: DEFAULTS,
                };

                if (!window.RADIANT_VAULT_MANUAL) ready(mount);
            })();
        </script>
    </body>
</html>
